mapper.insert:
INSERT  /* isry.couns.constt.medscsnntabrd.mapper.BbscttListMapper.insertMemo : 비밀게시판 메모등록 */
INTO
        AYA160
(
        RFRNC_NO
    ,   BBSCTT_ESNTAL_NO
    ,   BBSCTT_TYPE_SE_CD
    ,   CONSTT_ID
    ,   MEMO_NM
    ,   FRST_RGTR_ID
    ,   FRST_REG_DT
    ,   LAST_MDFR_ID
    ,   LAST_MDFCN_DT
)
VALUES
(
        AYA160_SQ01.NEXTVAL
    ,   #{BBSCTT_ESNTAL_NO}
    ,   #{BBSCTT_TYPE_SE_CD}
    ,   #{CONSTT_ID}
    ,   #{MEMO_NM}
    ,   #{FRST_RGTR_ID}
    ,   SYSDATE
    ,   #{LAST_MDFR_ID}
    ,   SYSDATE
)

