/* isry.couns.constt.medscsnntabrd.mapper.BbssolListMapper.solContentList : 솔로봇템플릿이력목록 */
select SLRBT_DSCSN_SCLAS_SE_CD , CHG_AFTR_CNTT_CN , DEL_YN , FRST_RGTR_ID , TO_CHAR(FRST_REG_DT, 'YYYYMMDD') FRST_REG_DT , LAST_MDFR_ID , TO_CHAR(LAST_MDFCN_DT, 'YYYYMMDD') LAST_MDFCN_DT from AYE310 where 1=1
AND SLRBT_DSCSN_SCLAS_SE_CD = #{SLRBT_DSCSN_SCLAS_SE_CD}
order by FRST_REG_DT desc

mapper.update:

/* isry.couns.constt.medscsnntabrd.mapper.BbssolListMapper.updateAYE300 : 솔로봇템플릿저장 */

update AYE300
set CHG_AFTR_CNTT_CN = #{CHG_AFTR_CNTT_CN}
, LAST_MDFR_ID = #{LAST_MDFR_ID}
, LAST_MDFCN_DT = SYSDATE
where SLRBT_DSCSN_SCLAS_SE_CD = #{SLRBT_DSCSN_SCLAS_SE_CD}

